        ; load.b r97.b,#10.b
        ; call p8b_txt.p8s_chrout(r97.b@s10)
    moveq  #10,d0
    bsr  p8b_txt.p8s_chrout
        ; return
    rts
; End of subroutine: p8b_txt.p8s_nl

