; ---- Subroutine: sys.die ----

    ALIGN 2

sys.die:
            moveq   #0,d0
            move.w  12(a5),d0
            lea      .alert(pc),a1
            lea      .alert_limit(pc),a3
            move.w   #20,(a1)+
            move.b   #16,(a1)+
            lea      .prefix(pc),a2
.copy_prefix:
            move.b   (a2)+,d1
            beq.s    .copy_code
            move.b   d1,(a1)+
            bra.s    .copy_prefix
.copy_code:
            move.w  12(a5),d2
            moveq    #3,d4
.copy_code_digit:
            move.w   d2,d3
            lsr.w    #8,d3
            lsr.w    #4,d3
            andi.w   #$000f,d3
            cmpi.w   #10,d3
            bcs.s    .copy_code_number
            addi.w   #'A'-10,d3
            bra.s    .copy_code_store
.copy_code_number:
            addi.w   #'0',d3
.copy_code_store:
            move.b   d3,(a1)+
            lsl.w    #4,d2
            dbra     d4,.copy_code_digit
            clr.b    (a1)+
            move.b   #1,(a1)+
            move.w   #20,(a1)+
            move.b   #32,(a1)+
.copy_message:
            move.l   8(a5),a0
.copy_message_loop:
            cmpa.l   a3,a1
            bhi.s    .message_full
            move.b   (a0)+,d1
            move.b   d1,(a1)+
            bne.s    .copy_message_loop
            clr.b    (a1)
            bra.s    .display
.message_full:
            subq.l   #1,a1
            clr.b    (a1)
            clr.b    1(a1)
.display:
            moveq   #48,d1
            movea.l  sys.IntuitionBase,a6
            lea      .alert(pc),a0
            jsr      -90(a6)
            moveq   #0,d0
            move.w  12(a5),d0
            jmp      sys.exit

            even
.alert:
            ds.b     158
.alert_limit:
            ds.b     2
.alert_end:
.prefix:
            dc.b     "PROGRAM DIED code $",0
            ; !notreached!
; End of subroutine: sys.die


; ---- Subroutine: sys.memset ----
    ALIGN 2

sys.memset:
            movea.l  d0,a0
            tst.w    d1
            beq      .done
            tst.b    d2
            beq      sys.memclear       ; tail-call: value==0

            ; save fill byte zero-extended
            moveq    #0,d3
            move.b   d2,d3

            ; align address to even for word/longword transfers
            move.l   a0,d0
            btst     #0,d0
            beq      .aligned
            move.b   d3,(a0)+
            subq.l   #1,d1
            beq      .done

.aligned:
            ; expand fill byte to all byte positions in d3
            move.l   d3,d0
            lsl.l    #8,d0
            or.l     d0,d3
            move.l   d3,d0
            swap     d0
            or.l     d0,d3

            ; longword fill (4 bytes per iteration)
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numbytes (zero-extended)
            lsr.l    #2,d0
            beq      .bytes
            subq.w   #1,d0
.loop_l:
            move.l   d3,(a0)+
            dbra     d0,.loop_l

            ; remaining bytes (0-3)
.bytes:
            and.w    #3,d1
            beq      .done
            subq.w   #1,d1
.loop_b:
            move.b   d3,(a0)+
            dbra     d1,.loop_b
.done:
            rts
; End of subroutine: sys.memset


; ---- Subroutine: sys.memclear ----
    ALIGN 2

sys.memclear:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numbytes (zero-extended)
            beq      .done

            ; align to even for word/longword access
            move.l   a0,d1
            btst     #0,d1
            beq      .compute
            clr.b    (a0)+
            subq.l   #1,d0
            beq      .done

.compute:
            move.l   d0,d1
            move.l   d1,d2
            and.w    #31,d2          ; d2 = tail bytes after 32-byte blocks
            lsr.l    #5,d1           ; d1 = number of 32-byte blocks
            move.l   d2,a2           ; a2 = tail bytes
            movea.l  d1,a1           ; a1 = block count (save before zeroing regs)

            ; point a0 past the last byte, so we can decrement with movem
            move.l   d1,d3
            lsl.l    #5,d3
            adda.l   d3,a0           ; a0 = end address
            movea.l  a0,a4           ; a4 = end address; the movem loop leaves a0 back at the start

            ; zero all data registers except d7 (d7 will be the loop counter, not in movem)
            move.l   d1,d7           ; d7 = block count (save before zeroing)
            moveq    #0,d0
            move.l   d0,d1
            move.l   d0,d2
            move.l   d0,d3
            move.l   d0,d4
            move.l   d0,d5
            move.l   d0,d6
            movea.l  d0,a1           ; also zero a1 (part of movem)

            ; bulk clear: 32 bytes per movem (d0-d6=28 bytes + a1=4 bytes), decrementing a0
            subq.w   #1,d7
            bmi      .tail
.loop_m:
            movem.l  d0-d6/a1,-(a0)
            dbra     d7,.loop_m

.tail:
            movea.l  a4,a0           ; a0 = end of the bulk region, where the tail bytes belong
            movea.l  a2,a3
            move.l   a3,d0           ; copy to data reg for shift/btst
            beq      .done
            move.l   d0,d1
            lsr.l    #2,d1           ; d1 = longwords in tail
            beq      .tail_words
            subq.l   #1,d1
.loop_l:
            clr.l    (a0)+
            subq.l   #1,d1
            bpl      .loop_l

.tail_words:
            btst     #1,d0
            beq      .tail_byte
            clr.w    (a0)+

.tail_byte:
            btst     #0,d0
            beq      .done
            clr.b    (a0)+
.done:
            rts
; End of subroutine: sys.memclear


; ---- Subroutine: sys.memsetw ----
    ALIGN 2

sys.memsetw:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numwords (zero-extended)
            beq      .done
            move.w   d2,d1           ; d1 = fill word value

            ; Create longword fill pattern: d1:d1
            move.w   d1,d2
            swap     d2
            move.w   d1,d2           ; d2 = d1 : d1

            ; longword fill (2 words at a time)
            move.l   d0,d3
            lsr.l    #1,d3           ; d3 = numwords / 2
            beq      .odd_word
            subq.w   #1,d3
.loop_l:
            move.l   d2,(a0)+
            dbra     d3,.loop_l

.odd_word:
            btst     #0,d0
            beq      .done
            move.w   d1,(a0)+

.done:
            rts
; End of subroutine: sys.memsetw


; ---- Subroutine: sys.memsetl ----
    ALIGN 2

sys.memsetl:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numlongs (zero-extended)
            beq      .done

            ; longword fill
            subq.w   #1,d0
.loop_l:
            move.l   d2,(a0)+
            dbra     d0,.loop_l

.done:
            rts
; End of subroutine: sys.memsetl


; Block: prog8_math

prog8_math:
; 68000 math routines that should always be included by the compiler

  SECTION .bss,bss

math._sqrt_l.value:    ds.l 1
math._sqrt_uw.value:   ds.w 1
math._sqrt_ub.value:   ds.b 1

  SECTION .text,code  ; back to code section


math._sqrt_ub:
    moveq  #0,d1
    clr.l  d0
    move.b  math._sqrt_ub.value,d0
    beq  .done_ub
    moveq  #4,d2
.loop_ub:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.w  d0,d3
    bhi  .skip_ub
    bset  d2,d1
.skip_ub:
    subq  #1,d2
    bpl  .loop_ub
.done_ub:
    move.b  d1,d0
    rts

math._sqrt_uw:
    moveq  #0,d1
    move.w  math._sqrt_uw.value,d0
    beq  .done_uw
    moveq  #8,d2
.loop_uw:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.l  d0,d3
    bhi  .skip_uw
    bset  d2,d1
.skip_uw:
    subq  #1,d2
    bpl  .loop_uw
.done_uw:
    move.b  d1,d0
    rts

math._sqrt_l:
    moveq  #0,d1
    move.l  math._sqrt_l.value,d0
    beq  .done_l
    moveq  #15,d2
.loop_l:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.l  d0,d3
    bhi  .skip_l
    bset  d2,d1
.skip_l:
    subq  #1,d2
    bpl  .loop_l
.done_l:
    move.w  d1,d0
    rts
; 68000 (amiga500) 32-bit multiplication / division / modulo
;
; The plain 68000 only has 8x8 and 16x16 multiply/divide instructions, so the
; 32-bit operations have to be built up from those. The routines below are
; written to integrate directly with the code generator: they take their
; arguments in registers (d0/d1) and return their results in registers, and the
; division/modulo share a single long-division core that produces both quotient
; and remainder at once.
;
; The p8_*32 wrapper routines use the amiga utility.library for a fast path on
; Kickstart 2.0+ (when sys.UtilityBase is non-zero), with a software fallback
; for Kickstart 1.3 (where utility.library is not available).

  SECTION .text,code

; d0 = d0 * d1  (signed or unsigned, keeping the low 32 bits)
; Uses four 16-bit partial products:  result = x0*y0 + (x0*y1 + x1*y0)<<16  (+ x1*y1<<32, dropped).
p8_mulsi3:
    move.w  d0,d2          ; d2 = x0 (low half of x)
    mulu.w  d1,d2          ; d2 = x0*y0
    move.l  d0,d3
    lsr.l   #8,d3
    lsr.l   #8,d3          ; d3 = x1 (high half of x)
    mulu.w  d1,d3          ; d3 = x1*y0
    swap    d1             ; d1 = y1 (high half of y)
    mulu.w  d0,d1          ; d1 = x0*y1
    add.l   d3,d1          ; d1 = x0*y1 + x1*y0  (the two cross terms)
    swap    d1
    clr.w   d1             ; d1 = (cross terms) << 16
    add.l   d1,d2          ; d2 = x0*y0 + cross<<16
    move.l  d2,d0
    rts

; Unsigned 32/32 -> 32: d0 = dividend, d1 = divisor  ->  d0 = quotient, d1 = remainder.
; Plain shift-and-subtract long division, 32 iterations, no 32-bit divide needed.
p8_udivmod32_sw:
    move.l  d1,d2          ; d2 = divisor
    beq.s   .divz          ; divide by zero: quotient 0, remainder = dividend
    moveq   #31,d3         ; 32 bit positions to process
    move.l  d0,d4          ; d4 = dividend (shifted through to feed the bits)
    clr.l   d0             ; d0 = quotient (built up)
    clr.l   d5             ; d5 = remainder (built up)
.loop:
    lsl.l   #1,d4          ; shift the next dividend bit out into the X flag
    roxl.l  #1,d5          ; remainder = (remainder<<1) | that dividend bit
    lsl.l   #1,d0          ; quotient <<= 1
    cmp.l   d2,d5
    blo.s   .next
    sub.l   d2,d5          ; remainder -= divisor
    addq.l  #1,d0          ; quotient |= 1
.next:
    dbf     d3,.loop
    move.l  d5,d1          ; remainder
    rts
.divz:
    move.l  d0,d1          ; remainder = dividend
    clr.l   d0             ; quotient = 0
    rts

; Signed 32/32 -> 32: d0 = dividend, d1 = divisor  ->  d0 = quotient, d1 = remainder.
; Computed with absolute values, then the signs are corrected: the quotient takes
; the sign of (dividend xor divisor), the remainder takes the sign of the dividend
; (truncating division, like C).
p8_sdivmod32_sw:
    move.l  d0,d6          ; d6 = dividend (keep original for sign)
    move.l  d1,d7
    eor.l   d6,d7          ; d7 bit31 set if the two signs differ
    tst.l   d0
    bpl.s   .nabs
    neg.l   d0             ; d0 = |dividend|
.nabs:
    tst.l   d1
    bpl.s   .dabs
    neg.l   d1             ; d1 = |divisor|
.dabs:
    jsr     p8_udivmod32_sw  ; d0 = |quotient|, d1 = |remainder|
    tst.l   d7
    bpl.s   .qpos
    neg.l   d0             ; flip quotient sign if signs differed
.qpos:
    tst.l   d6
    bpl.s   .rpos
    neg.l   d1             ; flip remainder sign to match dividend
.rpos:
    rts

; Wrappers. d0/d1 in, d0 (and d1 for divmod) out. When sys.UtilityBase is non-zero
; (Kickstart 2.0+) the amiga utility.library is used for a fast result; otherwise the
; software routines above are used.

; d0*d1 (signed) -> d0
p8_smult32:
    move.l  sys.UtilityBase,d2   ; scratch (d0=arg1, d1=arg2 preserved)
    beq.w   p8_mulsi3
    move.l  d2,a6
    jmp     -138(a6)      ; utility.library SMult32

; d0/d1 (signed) -> d0=quotient, d1=remainder
p8_sdivmod32:
    move.l  sys.UtilityBase,d2   ; scratch (d0=dividend, d1=divisor preserved)
    beq.w   p8_sdivmod32_sw
    move.l  d2,a6
    jmp     -150(a6)      ; utility.library SDivMod32

; Block: prog8_lib

prog8_lib:

; ---- Subroutine: prog8_lib.strcmp ----
    ALIGN 2

prog8_lib.strcmp:
            movea.l  d0,a0
            movea.l  d1,a1
.loop:
            move.b   (a0)+,d0
            move.b   (a1)+,d1
            cmp.b    d1,d0
            bne      .diff
            tst.b    d0
            bne      .loop
            moveq    #0,d0
            rts
.diff:
            blo      .less
            moveq    #1,d0
            rts
.less:
            moveq    #-1,d0
            rts
; End of subroutine: prog8_lib.strcmp


