; ---- Subroutine: p8b_prog8_defer.p8s_defer_unwind_all ----

    ALIGN 2

p8b_prog8_defer.p8s_defer_unwind_all:
; stack frame: 2 bytes of locals, 0 bytes of arguments
    link  a5,#-2
    clr.w  -2(a5)
        ; loadm.b r557.b,[p8b_prog8_defer.p8v_defer_guard]
    move.b  p8b_prog8_defer.p8v_defer_guard,p8_regfile+1824
        ; cmpi.b r557.b,#0.b
    tst.b  p8_regfile+1824
        ; bsteq p8_label_gen_115
    beq  p8_label_gen_115
        ; return
    unlk  a5
    rts

p8_label_gen_115:
        ; storeim.b #1.b,[p8b_prog8_defer.p8v_defer_guard]
    move.b  #1,p8b_prog8_defer.p8v_defer_guard

p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_loop:
        ; loadm.w r558.w,[p8b_prog8_defer.p8v_defer_sp]
    move.w  p8b_prog8_defer.p8v_defer_sp,p8_regfile+1826
        ; cmpi.w r558.w,#0.w
    tst.w  p8_regfile+1826
        ; bsteq p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_done
    beq  p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_done
        ; decm.w [p8b_prog8_defer.p8v_defer_sp]
    subq.w  #1,p8b_prog8_defer.p8v_defer_sp
        ; loadm.w r559.w,[p8b_prog8_defer.p8v_defer_sp]
    move.w  p8b_prog8_defer.p8v_defer_sp,p8_regfile+1828
        ; loadx.b r560.b,[p8b_prog8_defer.p8v_defer_handler_stack+r559.w]
    move.w  p8_regfile+1828,d0
    lea  p8b_prog8_defer.p8v_defer_handler_stack,a0
    move.b  (a0,d0.w),d0
    move.b  d0,p8_regfile+1830
        ; ext.b r561.w,r560.b
    moveq  #0,d0
    move.b  p8_regfile+1830,d0
    move.w  d0,p8_regfile+1832
        ; storem.w r561.w,[frame:-2]
    move.w  p8_regfile+1832,-2(a5)
        ; loadm.w r562.w,[frame:-2]
    move.w  -2(a5),p8_regfile+1834
        ; cmpi.w r562.w,#1.w
    cmpi.w  #1,p8_regfile+1834
        ; bsteq p8_label_gen_117
    beq  p8_label_gen_117
        ; jump p8_label_gen_116
    bra  p8_label_gen_116

p8_label_gen_117:
        ; call dos.read_file.prog8_invoke_defers()
    bsr  dos.read_file.prog8_invoke_defers
        ; jump p8_label_gen_116
    bra  p8_label_gen_116

p8_label_gen_116:
